WITH remaining_keys AS (SELECT product_id, store_id FROM inventory INTERSECT SELECT product_id, store_id FROM inventory WHERE quantity != 218), verified AS (SELECT s.* FROM inventory s JOIN remaining_keys k ON s.product_id = k.product_id AND s.store_id = k.store_id) SELECT CASE WHEN quantity >= 194 THEN 'HIGH' ELSE 'LOW' END AS quantity_tier, DATE_TRUNC('MONTH', last_restock) AS activity_month, STDDEV_SAMP(quantity) AS quantity_stddev, BIT_OR(quantity) AS quantity_bit_or, GROUPING(CASE WHEN quantity >= 194 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM verified GROUP BY ROLLUP (CASE WHEN quantity >= 194 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', last_restock)) ORDER BY activity_month DESC
